import { readFile, rm } from 'node:fs/promises';
import path from 'node:path';
/**
 * Read and delete the manifest Architect generated during autoinstall.
 * Arc moves it to `node_modules/_arc-autoinstall/` after the install.
 * Has a timestamp, so it must be deleted to avoid hash changes on every deploy.
 */
export async function takeAutoInstallManifest(installDir) {
    const file = path.join(installDir, 'node_modules', '_arc-autoinstall', 'package.json');
    let manifest;
    try {
        manifest = JSON.parse(await readFile(file, 'utf8'));
    }
    catch {
        // no autoinstall happened, or the file is unreadable
    }
    try {
        await rm(file, { force: true });
    }
    catch {
        // best effort
    }
    return manifest;
}
/**
 * Describe a function's dependencies from the manifest that declared them.
 * The user's own package.json wins. Otherwise the Architect autoinstall manifest is used.
 */
export async function getDependencyInfo({ sourceDir, autoInstall, bundled, }) {
    const declared = await readDeclaredDependencies(sourceDir);
    if (declared && Object.keys(declared).length > 0) {
        return {
            dependencySource: 'manifest',
            dependencyCount: Object.keys(declared).length,
            dependencies: declared,
        };
    }
    if (autoInstall) {
        const dependencies = autoInstall.dependencies ?? {};
        return {
            dependencySource: 'autoinstall',
            dependencyCount: Object.keys(dependencies).length,
            dependencies,
            parsedFileCount: autoInstall._parsed?.length,
        };
    }
    return { dependencySource: bundled ? 'bundled' : 'none', dependencyCount: 0 };
}
async function readDeclaredDependencies(dir) {
    try {
        const pkg = JSON.parse(await readFile(path.join(dir, 'package.json'), 'utf8'));
        return pkg.dependencies;
    }
    catch {
        return undefined;
    }
}
